import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long a = fs.nextLong();
        long b = fs.nextLong();
        long c = fs.nextLong();
        long l = fs.nextLong();

        long[] s = new long[]{a, b, c};
        Arrays.sort(s);
        a = s[0];
        b = s[1];
        c = s[2];

        long total = (l + 1) * (l + 2) / 2;

        long bad = 0;

        bad += countBad(a, b, c, l);
        bad += countBad(b, a, c, l);
        bad += countBad(c, a, b, l);

        System.out.println(total - bad);
    }

    private static long countBad(long x, long y, long z, long l) {
        long res = 0;
        long maxDx = l;
        for (long dx = 0; dx <= maxDx; dx++) {
            long sumYZ = y + z;
            long minDyDz = sumYZ - x - dx + 1;
            if (minDyDz <= 0) continue;
            long maxDyDz = l - dx;
            if (maxDyDz < minDyDz) continue;
            long n = maxDyDz - minDyDz + 1;
            res += n;
        }
        return res;
    }

    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static long count(long a, long b, long c, long l) {
        long res = 0;
        for (long x = 0; x <= l; x++) {
            long A = a + x;
            long rem = l - x;
            long B = b;
            long C = c;

            long total = rem + 1;
            long bad = 0;

            // Case 1: B + C <= A (degenerate or impossible)
            long t1 = A - B - C;
            if (t1 >= 0) {
                long maxBC = rem;
                long minBC = t1;
                if (minBC <= maxBC) {
                    long countBC = maxBC - minBC + 1;
                    bad += countBC;
                }
            }

            // Case 2: B + A <= C
            long t2 = C - B - A;
            if (t2 >= 0) {
                long maxCA = rem;
                long minCA = t2;
                if (minCA <= maxCA) {
                    long countCA = maxCA - minCA + 1;
                    bad += countCA;
                }
            }

            // Case 3: C + A <= B
            long t3 = B - C - A;
            if (t3 >= 0) {
                long maxBA = rem;
                long minBA = t3;
                if (minBA <= maxBA) {
                    long countBA = maxBA - minBA + 1;
                    bad += countBA;
                }
            }

            res += total - bad;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());
        long c = Long.parseLong(st.nextToken());
        long l = Long.parseLong(st.nextToken());
        System.out.println(count(a, b, c, l));
    }
}

import java.io.*;
