public class Main {
    static long countInvalid(long x, long y, long z, long l) {
        long res = 0;
        long maxInc = l;

        long low = 0;
        long high = maxInc;
        while (low <= high) {
            long mid = (low + high) >> 1;
            long X = x + mid;
            long sumYZ = y + z + (l - mid);
            if (X >= sumYZ) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        long start = low;
        if (start > maxInc) return 0;

        for (long dx = start; dx <= maxInc; dx++) {
            long X = x + dx;
            long rem = l - dx;
            long minYZ = Math.max(0, X - (y + z));
            if (minYZ > rem) continue;
            long ways = rem - minYZ + 1;
            res += ways;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());
        long c = Long.parseLong(st.nextToken());
        long l = Long.parseLong(st.nextToken());

        long total = (l + 1) * (l + 2) / 2;

        long invalid = 0;
        invalid += countInvalid(a, b, c, l);
        invalid += countInvalid(b, a, c, l);
        invalid += countInvalid(c, a, b, l);

        long ans = total - invalid;
        System.out.println(ans);
    }
}

