public class Main {
    static long count(long a, long b, long c, long l) {
        long res = 0;
        for (long da = 0; da <= l; da++) {
            long A = a + da;
            long remaining = l - da;
            long maxDb = remaining;
            long maxDc = remaining;
            long totalPairs = (remaining + 1) * (remaining + 2) / 2;

            long bad = 0;

            // Case 1: A >= B + C  =>  A >= b+db + c+dc => db + dc <= b + c - A
            long limit1 = b + c - A;
            if (limit1 >= 0) {
                long x = Math.min(limit1, remaining);
                bad += (x + 1) * (x + 2) / 2;
            }

            // Case 2: B >= A + C  =>  b+db >= A + c+dc => db - dc >= A + c - b
            long k2 = A + c - b;
            if (k2 <= remaining) {
                long start = Math.max(0, k2);
                long end = remaining;
                long n = end - start + 1;
                if (n > 0) {
                    long first = start;
                    long last = end;
                    long sumDb = n * (first + last) / 2;
                    long sumDc = n * remaining;
                    bad += sumDb - sumDc;
                }
            }

            // Case 3: C >= A + B  =>  c+dc >= A + b+db => dc - db >= A + b - c
            long k3 = A + b - c;
            if (k3 <= remaining) {
                long start = Math.max(0, k3);
                long end = remaining;
                long n = end - start + 1;
                if (n > 0) {
                    long first = start;
                    long last = end;
                    long sumDc = n * (first + last) / 2;
                    long sumDb = n * remaining;
                    bad += sumDc - sumDb;
                }
            }

            res += totalPairs - bad;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());
        long c = Long.parseLong(st.nextToken());
        long l = Long.parseLong(st.nextToken());

        long ans = count(a, b, c, l);
        System.out.println(ans);
    }
}

