public class Main {
    static long countForOrder(long a, long b, long c, long l) {
        long res = 0;
        for (long da = 0; da <= l; da++) {
            long A = a + da;
            long maxSum = b + c + (l - da);
            long minSum = A + 1;
            if (maxSum < minSum) continue;
            long maxX = maxSum - minSum;
            long maxDb = Math.min(l - da, maxX);
            if (maxDb < 0) continue;
            long minDb = Math.max(0, c + (l - da) - A);
            if (minDb > maxDb) continue;
            long cnt = maxDb - minDb + 1;
            res += cnt;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());
        long c = Long.parseLong(st.nextToken());
        long l = Long.parseLong(st.nextToken());

        long ans = 0;
        ans += countForOrder(a, b, c, l);
        ans += countForOrder(b, a, c, l);
        ans += countForOrder(c, a, b, l);

        System.out.println(ans);
    }
}

