public class Main {
    static long count(long A, long B, long C, long L) {
        long res = 0;
        for (long x = 0; x <= L; x++) {
            long a = A + x;
            long remaining = L - x;

            long yMin = 0;
            long yMax = remaining;

            long zMin = 0;
            long zMax = remaining - yMin;

            long total = (remaining + 1) * (remaining + 2) / 2;

            long need = a - B - C;
            if (need <= 0) {
                res += total;
                continue;
            }

            long bad = 0;
            long yStart = Math.max(0, need - C);
            long yEnd = Math.min(remaining, need - 1);
            if (yStart <= yEnd) {
                long k = yEnd - yStart + 1;
                long first = remaining - yStart + 1;
                long last = remaining - yEnd + 1;
                bad = k * (first + last) / 2;
            }
            res += total - bad;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
