        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());
        long c = Long.parseLong(st.nextToken());
        long l = Long.parseLong(st.nextToken());

        long ans = 0;
        ans += count(a, b, c, l);
        ans += count(b, a, c, l);
        ans += count(c, a, b, l);

        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static long countBad(long x, long y, long z, long l) {
        long bad = 0;
        long maxIncZ = l;
        for (long incZ = 0; incZ <= maxIncZ; incZ++) {
            long zNew = z + incZ;
            long sumXY = x + y;
            long need = zNew - sumXY + 1;
            if (need <= 0) continue;
            long remaining = l - incZ;
            long maxIncX = remaining;
            long maxIncY = remaining;
            long maxPossible = maxIncX + maxIncY;
            if (maxPossible < need) continue;
            long minIncX = Math.max(0, need - maxIncY);
            long maxIncXValid = Math.min(maxIncX, need);
            if (minIncX > maxIncXValid) continue;
            bad += (maxIncXValid - minIncX + 1);
        }
        return bad;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long a = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());
        long c = Long.parseLong(st.nextToken());
        long l = Long.parseLong(st.nextToken());

        long total = (l + 1) * (l + 2) / 2;

        long bad = 0;
        bad += countBad(a, b, c, l);
        bad += countBad(a, c, b, l);
        bad += countBad(b, c, a, l);

        long ans = total - bad;
        System.out.println(ans);
    }
}
